package com.loja.checkout;

import com.loja.checkout.dto.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

import java.math.BigDecimal;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CheckoutControllerTest {

    @LocalServerPort
    private int port;

    @Autowired
    private TestRestTemplate restTemplate;

    @Test
    void testEndpointResumoSucesso() {
        PedidoRequest pedido = new PedidoRequest(
            List.of(
                new ItemCarrinho("Camiseta", new BigDecimal("79.90"), 2, new BigDecimal("0.30")),
                new ItemCarrinho("Tênis", new BigDecimal("249.90"), 1, new BigDecimal("1.20"))
            ),
            "EXPRESSA",
            "BEMVINDO10",
            "PIX",
            1,
            "BRONZE",
            "NORTE"
        );

        ResponseEntity<ResumoResponse> response = restTemplate.postForEntity(
            "http://localhost:" + port + "/checkout/resumo",
            pedido,
            ResumoResponse.class
        );

        assertEquals(HttpStatus.OK, response.getStatusCode());
        assertNotNull(response.getBody());
        assertEquals(new BigDecimal("409.70"), response.getBody().subtotalProdutos());
        assertEquals(new BigDecimal("391.47"), response.getBody().totalFinal());
    }

    @Test
    void testEndpointResumoErro() {
        PedidoRequest pedido = new PedidoRequest(
            List.of(new ItemCarrinho("Teste", new BigDecimal("100.00"), 1, new BigDecimal("1.0"))),
            "ECONOMICA",
            "CUPOMINVALIDO",
            "PIX",
            1,
            "BRONZE",
            "SUDESTE"
        );

        ResponseEntity<ErroResponse> response = restTemplate.postForEntity(
            "http://localhost:" + port + "/checkout/resumo",
            pedido,
            ErroResponse.class
        );

        assertEquals(HttpStatus.BAD_REQUEST, response.getStatusCode());
        assertNotNull(response.getBody());
        assertEquals("CUPOM_INVALIDO", response.getBody().erro());
    }
}

